class Solution {
public:
    bool canReach(vector<int>& arr, int start) {
        int n = arr.size();
        vector<bool> visited(n, false);
        queue<int> q;
        q.push(start);
        visited[start] = true;
        while (!q.empty()) {
            int i = q.front();
            q.pop();
            if (arr[i] == 0) return true;
            int fwd = i + arr[i];
            if (fwd < n && !visited[fwd]) {
                visited[fwd] = true;
                q.push(fwd);
            }
            int bwd = i - arr[i];
            if (bwd >= 0 && !visited[bwd]) {
                visited[bwd] = true;
                q.push(bwd);
            }
        }
        return false;
    }
};
